/**
 * @returns {Promise<void>}
 */
async function you_sanity_check() {   // wizcmds.c:1402
    let mtmp = null;
    if (u.uswallow && !u.ustuck) {
        /* this probably ought to be panic() */
        await impossible($C`sanity_check: swallowed by nothing?`);
        await display_nhwindow()($G.WIN_MESSAGE, TRUE);
        /* try to recover from whatever the problem is */
        u.uswallow = 0;
        u.uswldtim = 0;
        await docrt();
    }
    if ((mtmp = svl.level.monsters[u.ux][u.uy]) !== null) {
        /* u.usteed isn't on the map */
        if (u.ustuck !== mtmp) {
            await impossible($C`sanity_check: you over monster`);
        }
    }
    /* [should we also check for (u.uhp < 1), (Upolyd && u.mh < 1),
       and (u.uen < 0) here?] */
    if (u.uhp > u.uhpmax) {
        await impossible($C`current hero health (%d) better than maximum? (%d)`,
            u.uhp, u.uhpmax);
        u.uhp = u.uhpmax;
    }
    if (Upolyd() && u.mh > u.mhmax) {
        await impossible(
            $C`current hero health as monster (%d) better than maximum? (%d)`,
            u.mh, u.mhmax);
        u.mh = u.mhmax;
    }
    if (u.uen > u.uenmax) {
        await impossible($C`current hero energy (%d) better than maximum? (%d)`,
            u.uen, u.uenmax);
        u.uen = u.uenmax;
    }
    await check_wornmask_slots();
    await check_invent_gold($C`invent`);
}
